<?php
declare(strict_types=1);namespace Vendi\Integrations\WhatsApp;use PDO;use RuntimeException;use Vendi\Integrations\HttpClient;
final class WhatsAppService{public function __construct(private PDO$db,private ?HttpClient$http=null){}private function cfg(int$b):array{$q=$this->db->prepare("SELECT config_json FROM integration_credentials WHERE business_id=? AND provider='whatsapp' AND active=1 ORDER BY branch_id IS NOT NULL DESC LIMIT 1");$q->execute([$b]);$c=json_decode((string)$q->fetchColumn(),true)?:[];if(empty($c['access_token'])||empty($c['phone_number_id']))throw new RuntimeException('WhatsApp no está configurado.');return$c;}public function sendText(int$b,string$to,string$text):array{$c=$this->cfg($b);$url='https://graph.facebook.com/'.($c['graph_version']??'v23.0').'/'.$c['phone_number_id'].'/messages';return($this->http??new HttpClient)->request('POST',$url,['Authorization'=>'Bearer '.$c['access_token']],['messaging_product'=>'whatsapp','recipient_type'=>'individual','to'=>preg_replace('/\D+/','',$to),'type'=>'text','text'=>['preview_url'=>false,'body'=>$text]]);}public function verifyWebhook(array$q):string{if(($q['hub_mode']??$q['hub.mode']??'')!=='subscribe')throw new RuntimeException('Webhook inválido.');$token=(string)($q['hub_verify_token']??$q['hub.verify_token']??'');$s=$this->db->query("SELECT config_json FROM integration_credentials WHERE provider='whatsapp' AND active=1");foreach($s->fetchAll(PDO::FETCH_COLUMN)as$j){$c=json_decode((string)$j,true)?:[];if(!empty($c['verify_token'])&&hash_equals((string)$c['verify_token'],$token))return(string)($q['hub_challenge']??$q['hub.challenge']??'');}throw new RuntimeException('Token de webhook inválido.');}public function receive(array$p):void{$changes=$p['entry'][0]['changes'][0]['value']??[];foreach(($changes['messages']??[])as$m){$phone=(string)($m['from']??'');$text=(string)($m['text']['body']??'');if(!$phone||!$text)continue;$metaPhone=(string)($changes['metadata']['phone_number_id']??'');$q=$this->db->prepare("SELECT business_id,branch_id FROM integration_credentials WHERE provider='whatsapp' AND active=1 AND config_json LIKE ? LIMIT 1");$q->execute(['%'.addcslashes($metaPhone,'%_').'%']);$scope=$q->fetch();if(!$scope)continue;$ext=(string)($m['id']??'');$i=$this->db->prepare("INSERT IGNORE INTO orders(business_id,branch_id,source,external_id,status,phone,payload_json) VALUES(?,?,'whatsapp',?,'new',?,?)");$i->execute([(int)$scope['business_id'],(int)($scope['branch_id']??0),$ext,$phone,json_encode(['message'=>$text,'raw'=>$m],JSON_UNESCAPED_UNICODE)]);}}}
